namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = "";
    public string Code { get; set; } = "";
    public string Description { get; set; } = "";
}

public class Course
{
    public int Id { get; set; }
    public int DepartmentId { get; set; }
    public string Code { get; set; } = "";
    public string Title { get; set; } = "";
    public string Description { get; set; } = "";
    public int Credits { get; set; }
    public string Schedule { get; set; } = "";
    public string InstructorName { get; set; } = "";
    public string InstructorBio { get; set; } = "";
    public bool IsFeatured { get; set; }
}

public class EnrollmentRequest
{
    public string StudentName { get; set; } = "";
    public string StudentId { get; set; } = "";
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments =
    [
        new() { Id = 1, Name = "Computer Science", Code = "CS", Description = "Study of computation, algorithms, and information systems." },
        new() { Id = 2, Name = "Mathematics", Code = "MATH", Description = "Study of numbers, structures, and patterns." },
        new() { Id = 3, Name = "Physics", Code = "PHYS", Description = "Study of matter, energy, and the fundamental forces of nature." },
        new() { Id = 4, Name = "English", Code = "ENG", Description = "Study of literature, writing, and language." },
        new() { Id = 5, Name = "History", Code = "HIST", Description = "Study of past events and civilizations." },
    ];

    private readonly List<Course> _courses =
    [
        new() { Id = 1, DepartmentId = 1, Code = "CS 101", Title = "Introduction to Programming", Description = "Fundamentals of programming using Python. Topics include variables, control flow, functions, and basic data structures.", Credits = 3, Schedule = "MWF 9:00–9:50 AM", InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen has 15 years of experience teaching introductory CS courses and researches CS education pedagogy.", IsFeatured = true },
        new() { Id = 2, DepartmentId = 1, Code = "CS 201", Title = "Data Structures & Algorithms", Description = "Design and analysis of fundamental data structures and algorithms including trees, graphs, sorting, and searching.", Credits = 4, Schedule = "TTh 10:30–11:50 AM", InstructorName = "Dr. James Park", InstructorBio = "Dr. Park specializes in algorithm optimization and has published extensively on graph theory." },
        new() { Id = 3, DepartmentId = 1, Code = "CS 310", Title = "Database Systems", Description = "Relational database design, SQL, normalization, indexing, and transaction management.", Credits = 3, Schedule = "MWF 1:00–1:50 PM", InstructorName = "Dr. Maria Lopez", InstructorBio = "Dr. Lopez worked in industry at major tech companies before joining academia. Her research focuses on distributed databases." },
        new() { Id = 4, DepartmentId = 1, Code = "CS 450", Title = "Machine Learning", Description = "Supervised and unsupervised learning, neural networks, and practical applications of ML in data science.", Credits = 3, Schedule = "TTh 2:00–3:20 PM", InstructorName = "Dr. Alan Turing Jr.", InstructorBio = "Dr. Turing Jr. leads the university's AI research lab and has industry partnerships with leading ML companies.", IsFeatured = true },
        new() { Id = 5, DepartmentId = 2, Code = "MATH 101", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions with applications.", Credits = 4, Schedule = "MWF 8:00–8:50 AM", InstructorName = "Dr. Robert Kim", InstructorBio = "Dr. Kim is an award-winning educator known for making calculus accessible to all students." },
        new() { Id = 6, DepartmentId = 2, Code = "MATH 201", Title = "Linear Algebra", Description = "Vector spaces, matrices, linear transformations, eigenvalues, and applications.", Credits = 3, Schedule = "TTh 9:00–10:20 AM", InstructorName = "Dr. Elena Volkov", InstructorBio = "Dr. Volkov's research spans algebraic geometry and she brings real-world applications into every lecture.", IsFeatured = true },
        new() { Id = 7, DepartmentId = 2, Code = "MATH 310", Title = "Probability & Statistics", Description = "Probability theory, random variables, distributions, hypothesis testing, and regression.", Credits = 3, Schedule = "MWF 11:00–11:50 AM", InstructorName = "Dr. David Okafor", InstructorBio = "Dr. Okafor consults for biotech firms on statistical modeling and clinical trial design." },
        new() { Id = 8, DepartmentId = 3, Code = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes a weekly lab component.", Credits = 4, Schedule = "MWF 10:00–10:50 AM + Lab Th 2–4 PM", InstructorName = "Dr. Lisa Nguyen", InstructorBio = "Dr. Nguyen is an experimental physicist who has worked at CERN and brings hands-on experience to teaching." },
        new() { Id = 9, DepartmentId = 3, Code = "PHYS 201", Title = "Electromagnetism", Description = "Electric and magnetic fields, Maxwell's equations, electromagnetic waves, and optics.", Credits = 4, Schedule = "TTh 1:00–2:20 PM + Lab F 2–4 PM", InstructorName = "Dr. Marcus Webb", InstructorBio = "Dr. Webb's research focuses on photonics and he holds several patents in optical communication.", IsFeatured = true },
        new() { Id = 10, DepartmentId = 4, Code = "ENG 101", Title = "College Composition", Description = "Developing clear, persuasive academic writing through essays, research papers, and peer review.", Credits = 3, Schedule = "MWF 9:00–9:50 AM", InstructorName = "Prof. Katherine Holt", InstructorBio = "Prof. Holt is a published author and writing coach who emphasizes revision as a creative process." },
        new() { Id = 11, DepartmentId = 4, Code = "ENG 250", Title = "American Literature", Description = "Survey of major American literary works from the colonial era to the present day.", Credits = 3, Schedule = "TTh 11:00 AM–12:20 PM", InstructorName = "Dr. Thomas Grant", InstructorBio = "Dr. Grant specializes in 20th-century American fiction and has authored two acclaimed literary biographies." },
        new() { Id = 12, DepartmentId = 5, Code = "HIST 101", Title = "World History I", Description = "A survey of global civilizations from antiquity through the Renaissance.", Credits = 3, Schedule = "MWF 2:00–2:50 PM", InstructorName = "Dr. Amara Diallo", InstructorBio = "Dr. Diallo is an expert in African and Mediterranean history with fieldwork experience across three continents.", IsFeatured = true },
        new() { Id = 13, DepartmentId = 5, Code = "HIST 320", Title = "Modern European History", Description = "Political, social, and cultural transformations in Europe from the Enlightenment to the present.", Credits = 3, Schedule = "TTh 3:30–4:50 PM", InstructorName = "Dr. Friedrich Weber", InstructorBio = "Dr. Weber previously held a fellowship at the German Historical Institute and publishes on nationalism and modernity." },
    ];

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses() => _courses;

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public List<Course> GetCoursesByDepartment(int departmentId) =>
        _courses.Where(c => c.DepartmentId == departmentId).ToList();

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> SearchCourses(string? query, int? departmentId)
    {
        var results = _courses.AsEnumerable();

        if (departmentId.HasValue && departmentId.Value > 0)
            results = results.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(query))
        {
            var q = query.Trim().ToLowerInvariant();
            results = results.Where(c =>
                c.Title.Contains(q, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(q, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(q, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(q, StringComparison.OrdinalIgnoreCase));
        }

        return results.ToList();
    }

    public bool SubmitEnrollmentRequest(EnrollmentRequest request)
    {
        // In a real app, this would persist to a database
        return !string.IsNullOrWhiteSpace(request.StudentName)
            && !string.IsNullOrWhiteSpace(request.StudentId)
            && request.CourseId > 0;
    }
}

